def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1

    def fb_string():
        i = 1
        while True:
            if i % 3 == 0:
                yield 'F'
            if i % 5 == 0:
                yield 'B'
            i += 1

    def is_substring(s):
        it = iter(fb_string())
        for char in s:
            if char not in set(it):
                return False
            next(it)
        return True

    for _ in range(t):
        k = int(data[index])
        s = data[index+1]
        index += 2
        if is_substring(s):
            print('YES')
        else:
            print('NO')

def solve():
    import sys
    input = lambda: input().strip()

    def check_parity(a):
        odd_sum, even_sum = 0, 0
        for num in a:
            if num % 2 == 0:
                even_sum += num
            else:
                odd_sum += num
        return (odd_sum + even_sum) % 2 == 0 and odd_sum != 0 and even_sum != 0

    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))
        if check_parity(a):
            print("YES")
        else:
            print("NO")

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()

    def min_days(s):
        mem = set()
        days = 0
        for char in s:
            if char not in mem:
                mem.add(char)
                if len(mem) > 3:
                    mem = {char}
                    days += 1
        return days + 1

    t = int(data[0])
    results = []
    for i in range(1, t * 2 + 1, 2):
        results.append(min_days(data[i]))

    for result in results:
        print(result)

def solve():
    import sys

    def is_possible(n, k):
        if k == 1:
            return 'YES'
        if n % k == 0:
            return 'YES'
        if n % k > 1:
            return 'NO'
        return 'YES' if n >= 2 else 'NO'

    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2
        print(is_possible(n, k))

