def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input()
        res = []
        i = 0
        while i < n:
            ch = s[i]
            # find the next occurrence of ch after i
            j = i + 1
            while j < n and s[j] != ch:
                j += 1
            if j < n and s[j] == ch:
                res.append(ch)
                i = j + 1
            else:
                # This else should never happen based on problem guarantee
                i += 1
        print(''.join(res))

def solve(b, c, h):
    layers = min(b, c + h)
    return layers

def solve(n):
    def find_triplet(start):
        for end in range(start + 1, n // 3):
            if n - end - (n - end) % 3 == 0:
                return (n - end, n - end % 3, end)
        return None

def solve():
    n, *a = map(int, input().split())
    a = list(a)

    def is_even(x):
        return x % 2 == 0

    def valid_coloring():
        blue_sum = 0
        red_sum = 0

        for num in a:
            if blue_sum ^ is_even(num):
                return False
            if not blue_sum:
                blue_sum += num
            else:
                red_sum += num

        return blue_sum ^ red_sum

    for _ in range(n):
        if valid_coloring():
            print("YES")
        else:
            print("NO")

