def can_form_sum(n):
    def helper(k):
        if k < 0:
            return False
        if k == 0:
            return True
        return helper(k - 1) or (helper(k) and n >= 3 * helper(k))

    return helper(n)

# Main function to solve the problem
def solve(n):
    if can_form_sum(n):
        # Find the combination of powers of 3 that sum up to n
        powers = []
        while n >= 3:
            if n % 3 == 0:
                powers.append(n // 3)
                n -= n // 3
            else:
                return "NO"
        powers.append(n)
        return "YES\n".join([str(p) for p in powers])
    else:
        return "NO"

